namespace DAL { using System; using System.Configuration; using System.Data; using System.Data.SqlClient; using Entities; public class User { private string connectionString; public User() { connectionString = ConfigurationManager.ConnectionStrings["BDD_PoliMusic"].ConnectionString; } public Entities.User Login(string username, string hashedPassword) { Entities.User user = null; SqlConnection connection = null; SqlCommand command = null; SqlDataReader reader = null; try { connection = new SqlConnection(connectionString); connection.Open(); string query = "SELECT ID_USER, USERNAME, PASSWORD, EMAIL, BIRTHDAY, USER_PHOTO, USER_TYPE FROM TBL_USER WHERE USERNAME = @Username AND PASSWORD = @Password"; command = new SqlCommand(query, connection); command.Parameters.AddWithValue("@Username", username); command.Parameters.AddWithValue("@Password", hashedPassword); reader = command.ExecuteReader(); if (reader.Read()) { user = new Entities.User(); user.ID_USER = (int)reader["ID_USER"]; user.USERNAME = reader["USERNAME"].ToString(); user.PASSWORD = reader["PASSWORD"].ToString(); user.EMAIL = reader["EMAIL"].ToString(); user.BIRTHDAY = (DateTime)reader["BIRTHDAY"]; user.USER_PHOTO = reader["USER_PHOTO"].ToString(); user.USER_TYPE = reader["USER_TYPE"].ToString(); } } catch (SqlException ex) { throw new Exception("Error en login: " + ex.Message); } finally { if (reader != null) reader.Close(); if (command != null) command.Dispose(); if (connection != null) { connection.Close(); connection.Dispose(); } } return user; } public bool UserExists(string username) { SqlConnection connection = null; SqlCommand command = null; try { connection = new SqlConnection(connectionString); connection.Open(); string query = "SELECT COUNT(*) FROM TBL_USER WHERE USERNAME = @Username"; command = new SqlCommand(query, connection); command.Parameters.AddWithValue("@Username", username); object result = command.ExecuteScalar(); int count = (int)result; return count > 0; } catch (SqlException ex) { throw new Exception("Error verificando usuario: " + ex.Message); } finally { if (command != null) command.Dispose(); if (connection != null) { connection.Close(); connection.Dispose(); } } } public bool Register(Entities.User user) { SqlConnection connection = null; SqlCommand command = null; try { connection = new SqlConnection(connectionString); connection.Open(); string query = "INSERT INTO TBL_USER (USERNAME, PASSWORD, EMAIL, BIRTHDAY, USER_PHOTO, USER_TYPE) VALUES (@Username, @Password, @Email, @Birthday, @UserPhoto, @UserType)"; command = new SqlCommand(query, connection); command.Parameters.AddWithValue("@Username", user.USERNAME); command.Parameters.AddWithValue("@Password", user.PASSWORD); command.Parameters.AddWithValue("@Email", user.EMAIL); command.Parameters.AddWithValue("@Birthday", user.BIRTHDAY); command.Parameters.AddWithValue("@UserPhoto", user.USER_PHOTO); command.Parameters.AddWithValue("@UserType", user.USER_TYPE); int rowsAffected = command.ExecuteNonQuery(); return rowsAffected > 0; } catch (SqlException ex) { throw new Exception("Error al registrar: " + ex.Message); } finally { if (command != null) command.Dispose(); if (connection != null) { connection.Close(); connection.Dispose(); } } } } }
